import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
	//Don't have to see. start------------------------------------------
	private static List<String> inLine = new ArrayList<>();
	private static int index = 0;
	private static int max = 0;

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String line;
		while ((line = br.readLine()) != null) {
			inLine.add(line);
		}
		max = inLine.size();
		System.err.println("\n↑入力 ↓出力");
		solve();
	}

	private static boolean hasNext() {
		return index < max;
	}

	private static String next() {
		if (hasNext()) {
			return inLine.get(index++);
		} else {
			throw new ArrayIndexOutOfBoundsException("ArrayIndexOutOfBoundsException ‚There is no more input");
		}
	}

	private static int nextInt() {
		return Integer.parseInt(next());
	}

	private static String[] nextStrArray() {
		return next().split(" ");
	}

	private static int[] nextIntArray() {
		String[] tmp = next().split(" ");
		int[] ret = new int[tmp.length];
		for (int i = 0; i < tmp.length; i++) {
			ret[i] = Integer.parseInt(tmp[i]);
		}
		return ret;
	}

	private static char[] nextCharArray() {
		return next().toCharArray();
	}

	private static void myout(Object s) {
		System.out.println(s);
	}

	private static void myerr(Object s) {
		System.err.println("debug:" + s);
	}
	//Don't have to see. end------------------------------------------

	private static void solve() {
		int[] one = nextIntArray();
		int L = one[0];
		int R = one[1];
		int C = one[2];
		if (Math.abs(L - R) >= C) {
			myout((Math.min(Math.max(L, R), Math.min(L, R) + C)) * 2);
		} else {
			int diff = Math.abs(L - R);
			if (L > R) {
				R += diff;
			} else {
				L += diff;
			}
			C -= diff;
			myout(((int) Math.floor(C / 2) + L) * 2);
		}
	}
}
